<template>
  <div class="chart-card">
    <div class="chart-header">
      <div class="chart-header__left">
        <div class="chart-tag">{{ tagLabel }}</div>
        <h2 class="chart-title">{{ chartTitleText }}</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
      <div class="chart-header__legend">
        <div class="legend-item">
          <span class="legend-bar" style="background: linear-gradient(135deg,#22c55e,#f59e0b)"></span>{{ $t('charts.factGrn') }}
        </div>
        <div class="legend-item">
          <span class="legend-bar" style="background: rgba(148,163,184,0.6)"></span>{{ pastLegendLabel }}
        </div>
        <div class="legend-item">
          <span class="legend-line"></span>{{ $t('charts.pctLabel') }}
        </div>
      </div>
    </div>
    <div class="chart-wrap">
      <canvas ref="chartCanvas"></canvas>
    </div>
    <div class="managers-row">
      <div
          v-for="m in managers"
          :key="m.name"
          class="manager-chip"
          :style="{ borderColor: m.color + '55', background: m.color + '11' }"
      >
        <span class="chip-dot" :style="{ background: m.color }"></span>
        <span class="chip-name">{{ m.name }}</span>
        <span class="chip-pct" :style="{ color: m.color }">{{ m.pct }}%</span>
      </div>
    </div>
  </div>
</template>

<script>
import {markRaw} from 'vue'
import {Chart, registerables} from 'chart.js'
import {dataStore} from '@/operations/requests'
import { MANAGERS } from '@/config/managers.config'

Chart.register(...registerables)

function pctColor(pct) {
  if (pct >= 100) return '#22c55e'
  if (pct >= 90) return '#84cc16'
  if (pct >= 80) return '#f59e0b'
  if (pct >= 70) return '#f97316'
  return '#ef4444'
}
function fmtMln(v) {
  if (v == null) return '—'
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2).replace('.', ',') + ' млн'
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
  return String(v)
}
const barLabelsPlugin = {
  id: 'barLabels',
  afterDatasetsDraw(chart) {
    const {ctx: c, data} = chart
    const showShareBadge = chart.options.plugins?.barLabels?.showShareBadge ?? false

    // ── Подписи ФАКТ (цветные бары) ───────────────────────
    const barMeta = chart.getDatasetMeta(0)
    barMeta.data.forEach((bar, i) => {
      const pct = data.datasets[2].data[i]
      const color = data.datasets[0].borderColor[i]

      const text = pct + '%'
      c.save()
      c.font = 'bold 11px system-ui'
      const tw = c.measureText(text).width + 14
      const th = 20, tx = bar.x, ty = bar.y + 18
      c.beginPath()
      c.fillStyle = color + 'dd'
      c.roundRect(tx - tw / 2, ty - th / 2, tw, th, th / 2)
      c.fill()
      c.fillStyle = '#fff'
      c.textAlign = 'center'
      c.textBaseline = 'middle'
      c.fillText(text, tx, ty)
      c.restore()

      c.save()
      c.fillStyle = '#1e293b'
      c.font = '600 11px system-ui'
      c.textAlign = 'center'
      c.textBaseline = 'bottom'
      c.fillText(fmtMln(data.datasets[0].data[i]), bar.x, bar.y - 6)
      c.restore()
    })

    // ── Подписи СЕРЫЕ БАРЫ (пр.год или общий ТО) ─────────
    const pastMeta = chart.getDatasetMeta(1)
    pastMeta.data.forEach((bar, i) => {
      const pastVal = data.datasets[1].data[i]
      const factVal = data.datasets[0].data[i]
      if (!pastVal) return

      const fs = 10, th = 16, gap = 4, tx = bar.x
      // Значение — прижато к бару снизу
      const valBottom  = bar.y - gap
      // Бейдж — над значением с зазором 3px
      const badgeBottom = valBottom - fs - 3
      const badgeTop    = badgeBottom - th

      // Значение
      c.save()
      c.fillStyle = '#94a3b8'
      c.font = `500 ${fs}px system-ui`
      c.textAlign = 'center'
      c.textBaseline = 'bottom'
      c.fillText(fmtMln(pastVal), tx, valBottom)
      c.restore()

      if (!factVal) return

      if (showShareBadge) {
        // no_iphone: доля ТО без iPhone от общего ТО
        const share = Math.round((factVal / pastVal) * 100)
        const text = share + '%'
        c.save()
        c.font = `bold ${fs}px system-ui`
        const tw = c.measureText(text).width + 10
        c.beginPath()
        c.fillStyle = 'rgba(99,102,241,0.15)'
        c.roundRect(tx - tw / 2, badgeTop, tw, th, th / 2)
        c.fill()
        c.fillStyle = '#6366f1'
        c.textAlign = 'center'
        c.textBaseline = 'middle'
        c.fillText(text, tx, badgeTop + th / 2)
        c.restore()
      } else {
        // ТО: прирост к прошлому году
        const growth = Math.round(((factVal - pastVal) / pastVal) * 100)
        const isPos = growth >= 0
        const text = (isPos ? '▲ +' : '▼ ') + growth + '%'
        const color = isPos ? '#16a34a' : '#dc2626'
        const bgColor = isPos ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)'
        c.save()
        c.font = `bold ${fs}px system-ui`
        const tw = c.measureText(text).width + 10
        c.beginPath()
        c.fillStyle = bgColor
        c.roundRect(tx - tw / 2, badgeTop, tw, th, th / 2)
        c.fill()
        c.fillStyle = color
        c.textAlign = 'center'
        c.textBaseline = 'middle'
        c.fillText(text, tx, badgeTop + th / 2)
        c.restore()
      }
    })
  },
}

export default {
  name: 'AllManagersChart',
  props: {
    selectedDate: {
      type: String,
      default: '',
    },
    metricKey: {
      type: String,
      default: 'revenue', // 'revenue' | 'no_iphone'
    },
  },
  data() {
    return {
      managers: [],
      period: '',
    }
  },
  computed: {
    fields() {
      if (this.metricKey === 'no_iphone') {
        return { f: 'no_iphone_f', p: 'no_iphone_p', past: 'products_f' }  // второй столбец = общий ТО
      }
      return { f: 'products_f', p: 'products_p', past: 'products_past' }
    },
    tagLabel() {
      return this.metricKey === 'no_iphone'
          ? this.$t('metrics.no_iphone')
          : this.$t('charts.summaryTag')
    },
    chartTitleText() {
      return this.metricKey === 'no_iphone'
          ? this.$t('charts.noIphoneTitle')
          : this.$t('charts.revenueTitle')
    },
    pastLegendLabel() {
      return this.metricKey === 'no_iphone'
          ? this.$t('metrics.revenue')
          : this.$t('charts.lastYearGrn')
    },
  },
  created() {
    // Храним chart НЕ в data() — чтобы Vue не делал его реактивным
    this._chart = null
  },
  mounted() {
    this.initChart()
    this.refreshData()
  },
  beforeUnmount() {
    if (this._chart) {
      this._chart.destroy()
      this._chart = null
    }
  },
  watch: {
    selectedDate(newVal, oldVal) {
      if (newVal !== oldVal) {
        this.refreshData()
      }
    },
  },
  methods: {
    getFilteredData() {
      const { f, p, past } = this.fields
      const sources = MANAGERS.map(m => ({
        name: m.name,
        data: dataStore.getManagerData(m.id),
      }))

      return sources
          .filter(s => s.data && s.data.length)
          .map(s => {
            const row = this.selectedDate
                ? s.data.find(item => item.time === this.selectedDate)
                : s.data[0]

            if (!row) return null

            const pct = row[p]
                ? Math.round((row[f] / row[p]) * 1000) / 10
                : 0

            return {
              name: s.name,
              fact: row[f],
              past: row[past],
              pct,
              color: pctColor(pct),
              time: row.time,
            }
          })
          .filter(Boolean)
          .sort((a, b) => b.fact - a.fact)
    },
    initChart() {
      const t = this.$t.bind(this)
      const metricKey = this.metricKey
      const ctx = this.$refs.chartCanvas.getContext('2d')

      // markRaw — запрещает Vue оборачивать Chart в реактивный прокси
      this._chart = markRaw(new Chart(ctx, {
        data: {          labels: [],
          datasets: [
            {
              type: 'bar',
              label: t('charts.factGrn'),
              data: [],
              backgroundColor: [],
              borderColor: [],
              borderWidth: 2,
              borderRadius: 10,
              borderSkipped: false,
              yAxisID: 'yFact',
              order: 2,
            },
            {
              type: 'bar',
              label: metricKey === 'no_iphone' ? t('metrics.revenue') : t('charts.lastYearGrn'),
              data: [],
              backgroundColor: 'rgba(148,163,184,0.3)',
              borderColor: 'rgba(148,163,184,0.65)',
              borderWidth: 2,
              borderRadius: 10,
              borderSkipped: false,
              yAxisID: 'yFact',
              order: 3,
            },
            {
              type: 'line',
              label: t('charts.pctLabel'),
              data: [],
              borderColor: '#6366f1',
              backgroundColor: 'rgba(99,102,241,0.06)',
              borderWidth: 2.5,
              pointBackgroundColor: [],
              pointBorderColor: '#fff',
              pointBorderWidth: 2,
              pointRadius: 7,
              pointHoverRadius: 10,
              tension: 0.4,
              fill: true,
              yAxisID: 'yPct',
              order: 1,
            },
          ],
        },

        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: {duration: 500},
          interaction: {mode: 'index', intersect: false},

          plugins: {
            legend: {display: false},
            barLabels: { showShareBadge: metricKey === 'no_iphone' },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.92)',
              titleColor: '#e2e8f0',
              bodyColor: '#94a3b8',
              borderColor: 'rgba(255,255,255,0.08)',
              borderWidth: 1,
              padding: 14,
              cornerRadius: 12,
              titleFont: {size: 13, weight: '700'},
              bodyFont: {size: 12},
              callbacks: {
                label(ctx) {
                  if (ctx.datasetIndex === 0) return `  ${t('charts.factLabel')}: ${fmtMln(ctx.parsed.y)}`
                  if (ctx.datasetIndex === 1) {
                    if (metricKey === 'no_iphone') {
                      return `  ${t('metrics.revenue')}: ${fmtMln(ctx.parsed.y)}`
                    }
                    const pastVal = ctx.parsed.y
                    const factVal = ctx.chart.data.datasets[0].data[ctx.dataIndex]
                    const growth = pastVal ? Math.round(((factVal - pastVal) / pastVal) * 100) : 0
                    const sign = growth >= 0 ? '+' : ''
                    return `  ${t('charts.lastYearLabel')}: ${fmtMln(pastVal)}  (${sign}${growth}%)`
                  }
                  return `  ${t('charts.pctLabel')}: ${ctx.parsed.y}%`
                },
              },
            },
          },

          scales: {
            x: {
              grid: {display: false},
              border: {display: false},
              ticks: {color: '#64748b', font: {size: 12, weight: '600'}},
            },
            yFact: {
              type: 'linear',
              position: 'left',
              grid: {color: 'rgba(148,163,184,0.12)'},
              border: {display: false},
              ticks: {
                color: '#64748b',
                font: {size: 11},
                callback(v) {
                  if (v >= 1e6) return (v / 1e6).toFixed(1) + ' млн'
                  if (v >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
                  return v
                },
              },
            },
            yPct: {
              type: 'linear',
              position: 'right',
              min: 50,
              max: 150,
              grid: {display: false},
              border: {display: false},
              ticks: {
                color: '#6366f1',
                font: {size: 11},
                callback: v => v + '%',
              },
            },
          },
        },

        plugins: [barLabelsPlugin],
      }))
    },
    refreshData() {
      const raw = this.getFilteredData()
      if (!raw.length || !this._chart) return

      this.managers = raw
      this.period = raw[0]?.time || ''

      const ds = this._chart.data
      ds.labels = raw.map(m => m.name)
      ds.datasets[0].data = raw.map(m => m.fact)
      ds.datasets[0].backgroundColor = raw.map(m => m.color + 'bb')
      ds.datasets[0].borderColor = raw.map(m => m.color)
      ds.datasets[1].data = raw.map(m => m.past)
      ds.datasets[2].data = raw.map(m => m.pct)
      ds.datasets[2].pointBackgroundColor = raw.map(m => m.color)

      this._chart.update('active')
    },
  },
}
</script>

